inline bool run(){
 uint8_t proof[32],digest[32];ac::Bytes identity;secure::domain(identity,"AtomClip/DeviceId/v2");secure::append(identity,factory,sizeof(factory));
 if(!secure::sha(identity.data(),identity.size(),digest)||!secure::equal(digest,id,16)||!secure::proof(key,"AtomClip/v2/server",info,client,server,proof)||!secure::equal(proof,serverProof,32))return false;
 secure::Session c,d;if(!c.derive(key,info,client,server,true)||!d.derive(key,info,client,server,false))return false;
 ac::Bytes p=secure::bytes(plain,sizeof(plain)),encoded,decoded;
 if(!c.seal(p,encoded)||encoded!=secure::bytes(clientFrame,sizeof(clientFrame))||!d.open(encoded,decoded)||decoded!=p)return false;
 if(!d.seal(p,encoded)||encoded!=secure::bytes(serverFrame,sizeof(serverFrame))||!c.open(encoded,decoded)||decoded!=p)return false;
 if(d.open(secure::bytes(clientFrame,sizeof(clientFrame)),decoded)||d.active)return false;
 mbedtls_platform_zeroize(proof,sizeof(proof));mbedtls_platform_zeroize(digest,sizeof(digest));return true;
}
